test('store result summary is recomputed from card datasets', () => assert.match(storeSource,/const summary = summarizeHomeStoreCards\(cards\.map\(\(card\) => card\.dataset\), query, filter\)/));
test('store result summary localizes visible count', () => assert.match(storeSource,/homeStoreResultSummary[\s\S]*?replace\("\{visible\}", String\(summary\.visible\)\)/));
test('store result summary localizes total count', () => assert.match(storeSource,/replace\("\{total\}", String\(summary\.total\)\)/));
test('store result summary localizes added count', () => assert.match(storeSource,/replace\("\{added\}", String\(summary\.added\)\)/));
test('store result summary records visible dataset', () => assert.match(storeSource,/resultSummary\.dataset\.visible = String\(summary\.visible\)/));
test('store result summary records total dataset', () => assert.match(storeSource,/resultSummary\.dataset\.total = String\(summary\.total\)/));
test('store result summary records added dataset', () => assert.match(storeSource,/resultSummary\.dataset\.added = String\(summary\.added\)/));
test('store result summary records empty state', () => assert.match(storeSource,/resultSummary\.dataset\.state = summary\.visible > 0 \? "results" : "empty"/));
test('store root records visible count', () => assert.match(storeSource,/root\.dataset\.visibleCount = String\(summary\.visible\)/));
test('store root records total count', () => assert.match(storeSource,/root\.dataset\.totalCount = String\(summary\.total\)/));
test('store root records added count', () => assert.match(storeSource,/root\.dataset\.addedCount = String\(summary\.added\)/));
test('store tab counts derive from card datasets', () => assert.match(storeSource,/const tabCounts = buildHomeStoreTabCounts\(Array\.from\(root\.querySelectorAll<HTMLElement>\("\.sw-home-store__card"\)\)\.map\(\(card\) => card\.dataset\)\)/));
test('store tab count label includes count', () => assert.match(storeSource,/button\.textContent = `\$\{button\.dataset\.tabLabel \|\| ""\} · \$\{count\}`/));
test('store tab count dataset stays synchronized', () => assert.match(storeSource,/button\.dataset\.count = String\(count\)/));
test('store tab count aria label stays synchronized', () => assert.match(storeSource,/button\.setAttribute\("aria-label", `\$\{button\.dataset\.tabLabel \|\| ""\} · \$\{count\}`\)/));
test('store tab count describes live summary', () => assert.match(storeSource,/button\.setAttribute\("aria-describedby", resultSummary\?\.id \|\| "sw-home-store-result-summary"\)/));
test('store clear filters resets query', () => assert.match(storeSource,/storeQuery = "";\s*storeTab = "all";\s*root\.dataset\.query = ""/));
test('store clear filters resets active tab dataset', () => assert.match(storeSource,/root\.dataset\.activeTab = "all"/));
test('store clear filters clears search input', () => assert.match(storeSource,/searchInput\.value = "";\s*clearSearchButton\.hidden = true/));
test('store clear filters restores active tab aria state', () => assert.match(storeSource,/button\.setAttribute\("aria-selected", String\(active\)\);\s*button\.setAttribute\("aria-current", active \? "page" : "false"\)/));
test('store clear filters reapplies model before focus', () => assert.match(storeSource,/applyFilter\(\);\s*searchInput\.focus\(\)/));

// T-4074~T-4125: search, sorting, render restoration and provider lifecycle contracts.
test('store captures dialog opener', () => assert.match(storeSource,/const opener = document\.activeElement instanceof HTMLElement \? document\.activeElement : null/));
test('store dialog uses localized title', () => assert.match(storeSource,/title: this\.i18n\.homeStoreTitle/));
test('store desktop width is viewport bounded', () => assert.match(storeSource,/Math\.min\(960, Math\.round\(window\.innerWidth \* 0\.78\)\)/));
test('store desktop height is viewport bounded', () => assert.match(storeSource,/Math\.min\(720, Math\.round\(window\.innerHeight \* 0\.84\)\)/));
test('store aborts safely when root is missing', () => assert.match(storeSource,/const root = storeDialog\.element\.querySelector<HTMLElement>\("\.sw-home-store"\);\s*if \(!root\) return/));
test('store root uses region role', () => assert.match(storeSource,/root\.setAttribute\("role", "region"\)/));
test('store root uses localized accessible label', () => assert.match(storeSource,/root\.setAttribute\("aria-label", this\.i18n\.homeStoreTitle\)/));
test('store root records target device', () => assert.match(storeSource,/root\.dataset\.device = device/));
test('store state starts from query tab and sort defaults', () => assert.match(storeSource,/let storeQuery = "";\s*let storeTab = "all";\s*let storeSort = "relevance"/));
test('store render metadata starts idle at version zero', () => assert.match(storeSource,/root\.dataset\.renderVersion = "0";\s*root\.setAttribute\("aria-busy", "false"\)/));
test('store collapsed groups use local set state', () => assert.match(storeSource,/const collapsedGroups = new Set<string>\(\)/));
test('store render announces busy before rebuilding', () => assert.match(storeSource,/const renderStore = \(\) => \{\s*root\.setAttribute\("aria-busy", "true"\)/));
test('store render increments version monotonically', () => assert.match(storeSource,/String\(Number\(root\.dataset\.renderVersion \|\| "0"\) \+ 1\)/));
test('store render captures active element', () => assert.match(storeSource,/const activeElement = document\.activeElement instanceof HTMLElement \? document\.activeElement : null/));
test('store render captures scroll position', () => assert.match(storeSource,/const previousScrollTop = root\.scrollTop/));
test('store render initializes neutral focus snapshot', () => assert.match(storeSource,/let focusKind = "none";\s*let focusValue = ""/));
test('store render captures focused card identity', () => assert.match(storeSource,/if \(card\?\.dataset\.moduleId\) \{\s*focusKind = "card";\s*focusValue = card\.dataset\.moduleId/));
test('store render captures focused tab identity', () => assert.match(storeSource,/else if \(tab\?\.dataset\.tabKey\) \{\s*focusKind = "tab";\s*focusValue = tab\.dataset\.tabKey/));
test('store render captures focused group identity', () => assert.match(storeSource,/else if \(group\?\.dataset\.group\) \{\s*focusKind = "group";\s*focusValue = group\.dataset\.group/));
test('store render recognizes focused search input', () => assert.match(storeSource,/activeElement\.matches\("\.sw-home-store__search input"\)[\s\S]*?focusKind = "search"/));
test('store render recognizes focused sort control', () => assert.match(storeSource,/activeElement\.matches\("\.sw-home-store__sort"\)[\s\S]*?focusKind = "sort"/));
test('store render clears stale DOM before rebuild', () => assert.match(storeSource,/root\.innerHTML = "";\s*(?:\/\/[^\n]*\n\s*)*const storeFragment = document\.createDocumentFragment\(\);\s*const state = this\.getHomeState\(\)/));
test('store render mounts the assembled fragment once', () => assert.match(storeSource,/root\.appendChild\(storeFragment\);\s*applyFilter\(\)/));
test('store render reads current home state', () => assert.match(source, /const state = this\.getHomeState\(\)/));
test('store render scopes instances to device layout', () => assert.match(source, /\(state\.layouts\[device\] \|\| \[\]\) as Array<any>/));
test('store render resolves layout instance safely', () => assert.match(storeSource,/state\.instances\.find\(\(candidate: any\) => candidate\.instanceId === entry\.instanceId\)/));
test('store render builds layout and instance maps together', () => assert.match(storeSource,/instanceByModule\.set\(inst\.moduleId, entry\);\s*instanceStateByModule\.set\(inst\.moduleId, inst\)/));
test('store render lists modules for target device', () => assert.match(storeSource,/this\.homeRuntime\.listModules\(device\)\.forEach\(\(def: any\) => defs\.set\(def\.moduleId, def\)\)/));
test('store render admits built-in or registered third-party ids', () => assert.match(source, /this\.homeBuiltinAdapterIds\.has\(moduleId\) \|\| this\.homeThirdPartyIds\.has\(moduleId\)/));
test('store render records active ready count', () => assert.match(storeSource,/root\.dataset\.readyCount = String\(activeIds\.size\)/));
test('store search restores in-memory query', () => assert.match(storeSource,/searchInput\.value = storeQuery/));
test('store clear-search visibility follows query state', () => assert.match(storeSource,/clearSearchButton\.hidden = !storeQuery/));
test('store clear-search resets query and input together', () => assert.match(storeSource,/clearSearchButton\.addEventListener\("click", \(\) => \{\s*storeQuery = "";\s*searchInput\.value = ""/));
test('store clear-search hides itself', () => assert.match(storeSource,/searchInput\.value = "";\s*clearSearchButton\.hidden = true/));
test('store clear-search reapplies filter', () => assert.match(storeSource,/clearSearchButton\.hidden = true;\s*applyFilter\(\)/));
test('store clear-search returns focus', () => assert.match(storeSource,/applyFilter\(\);\s*searchInput\.focus\(\)/));
test('store search escape only handles non-empty query', () => assert.match(storeSource,/if \(event\.key !== "Escape" \|\| !searchInput\.value\) return/));
test('store search escape prevents default', () => assert.match(storeSource,/event\.preventDefault\(\);\s*clearSearchButton\.click\(\)/));
test('store search escape delegates to clear action', () => assert.match(storeSource,/clearSearchButton\.click\(\)/));
test('store sort offers relevance title status and category', () => assert.match(storeSource,/\{value: "relevance"[\s\S]*?\{value: "title"[\s\S]*?\{value: "status"[\s\S]*?\{value: "category"/));
test('store sort value is normalized before display', () => assert.match(storeSource,/sortSelect\.value = normalizeHomeStoreSort\(storeSort\)/));
test('store sort records current mode', () => assert.match(storeSource,/sortSelect\.dataset\.sort = storeSort/));
test('store sort controls result summary', () => assert.match(storeSource,/sortSelect\.setAttribute\("aria-controls", "sw-home-store-result-summary"\)/));
test('store sort change normalizes and rerenders', () => assert.match(storeSource,/sortSelect\.addEventListener\("change", \(\) => \{ storeSort = normalizeHomeStoreSort\(sortSelect\.value\); renderStore\(\); \}\)/));
test('store restore clamps scroll to rebuilt height', () => assert.match(storeSource,/root\.scrollTop = Math\.min\(previousScrollTop, root\.scrollHeight\)/));
test('store restore finds card by module identity', () => assert.match(storeSource,/find\(\(card\) => card\.dataset\.moduleId === focusValue && !card\.classList\.contains\("fn__none"\)\)/));
test('store restore focuses target without scrolling', () => assert.match(storeSource,/if \(target\) target\.focus\(\{preventScroll: true\}\)/));
test('store performs initial render immediately', () => assert.match(storeSource,/\r?\n        renderStore\(\);\r?\n        const handleModuleChange/));
test('store module refresh ignores detached roots', () => assert.match(storeSource,/const handleModuleChange = \(\) => \{\s*if \(!root\.isConnected\) return/));
test('store module refresh rerenders and notifies', () => assert.match(storeSource,/if \(!root\.isConnected\) return;\s*renderStore\(\);\s*onChanged\(\)/));
test('store registers module change listener', () => assert.match(source, /this\.homeModuleChangeListeners\.add\(handleModuleChange\)/));
test('store provider rescan is delayed and connection guarded', () => assert.match(storeSource,/window\.setTimeout\(\(\) => \{\s*if \(root\.isConnected\) renderStore\(\);\s*\}, 400\)/));
test('store destroy clears timer and module listener', () => assert.match(storeSource,/window\.clearTimeout\(rescanTimer\);\s*this\.homeModuleChangeListeners\.delete\(handleModuleChange\)/));
test('store destroy delegates then restores opener focus', () => assert.match(storeSource,/originalDestroy\(\);\s*if \(opener\?\.isConnected\) opener\.focus\(\)/));
